definition.script:
node {
  stage('Groovy logic') {
    def targets = ['api', 'web', 'worker']
    echo "Deploying ${targets.size()} services"
    targets.each { name ->
      echo "  deploying ${name}"
    }
  }
  stage('Try / catch') {
    try {
      sh 'echo risky command; exit 1'
    } catch (err) {
      echo "Caught a failure and handled it: ${err}"
    }
  }
  stage('Compute') {
    def total = (1..5).sum()
    echo "Sum of 1..5 = ${total}"
  }
}
